validator:
function validate(input) {
  const [{ HallEvents = [] }] = input;
  const date = /^\d{4}-\d{2}-\d{2}$/;
  for (const [hall, start, end] of HallEvents) {
    if (hall === null) return 'Every event needs a hall_id.';
    if (typeof start !== 'string' || !date.test(start) || typeof end !== 'string' || !date.test(end)) return 'start_day and end_day must be dates like 2023-01-13.';
    if (start > end) return `An event in hall ${hall} ends (${end}) before it starts (${start}).`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const day = offset => new Date(Date.UTC(2022, 11, 20) + offset * 86400000).toISOString().slice(0, 10);
  const count = small ? Math.floor(rand() * 9) : 1000;
  const halls = small ? 3 : 100, span = small ? 16 : 120, longest = small ? 4 : 8;
  const HallEvents = [];
  while (HallEvents.length < count) {
    // Now and then repeat an earlier row, since the table may hold duplicates.
    if (HallEvents.length && rand() < 0.12) { HallEvents.push([...HallEvents[Math.floor(rand() * HallEvents.length)]]); continue; }
    const start = Math.floor(rand() * span), length = Math.floor(rand() * (longest + 1));
    HallEvents.push([1 + Math.floor(rand() * halls), day(start), day(start + length)]);
  }
  return [{ HallEvents }];
}
